create Proc [dbo].[GetData] @FromDate as datetime,@ToDate as datetime,@Type as nvarchar(50) as if @Type = 'OrderNo' begin Select d.order_key,d.z_number as [Shift#],d.od as [Order#],d.order_time as [Order Time],d.order_type as [Order Type], isnull(o.sub_total,0) as Gross, isnull(o.cash_Sale,0) as CASH, isnull(o.credit_sale,0) as CREDIT, isnull(o.ent,0) as ENT, isnull(o.net_bill,0) as [Net Bill], '' as [Payment Type],d.status  as Status,d.Service_Status,d.is_delete from Shift_Opening s inner join Dine_In_Order d on s.z_report_number = d.z_number left join Order_Payment o on d.order_key = o.order_key  where s.opening_date between @FromDate and @ToDate and  d.status <> 1 order by d.od end else if @Type = 'AscAmount' begin Select d.order_key,d.z_number as [Shift#],d.od as [Order#],d.order_time as [Order Time],d.order_type as [Order Type], isnull(o.sub_total,0) as Gross, isnull(o.cash_Sale,0) as CASH, isnull(o.credit_sale,0) as CREDIT, isnull(o.ent,0) as ENT, isnull(o.net_bill,0) as [Net Bill], '' as [Payment Type],d.status  as Status,d.Service_Status,d.is_delete from Shift_Opening s inner join Dine_In_Order d on s.z_report_number = d.z_number left join Order_Payment o on d.order_key = o.order_key  where s.opening_date between @FromDate and @ToDate and  d.status <> 1 order by o.net_bill asc end else if @Type = 'descAmount' begin Select d.order_key,d.z_number as [Shift#],d.od as [Order#],d.order_time as [Order Time],d.order_type as [Order Type], isnull(o.sub_total,0) as Gross, isnull(o.cash_Sale,0) as CASH, isnull(o.credit_sale,0) as CREDIT, isnull(o.ent,0) as ENT, isnull(o.net_bill,0) as [Net Bill], '' as [Payment Type],d.status  as Status,d.Service_Status,d.is_delete from Shift_Opening s inner join Dine_In_Order d on s.z_report_number = d.z_number left join Order_Payment o on d.order_key = o.order_key  where s.opening_date between @FromDate and @ToDate and  d.status <> 1 order by o.net_bill desc end